class TestRollingWindowConfig:
    """Validation of the configuration dataclass."""

    def test_default_values(self):
        """Test that defaults are sensible and valid."""
        config = RollingWindowConfig(window_sizes=[10])
        assert config.min_periods is None
        assert config.include_zscore is True
        assert config.include_rate_of_change is True
        assert config.zscore_threshold == 3.0

    def test_frozen_dataclass(self):
        """Config should be immutable."""
        config = RollingWindowConfig(window_sizes=[10])
        with pytest.raises(Exception):
            config.window_sizes = [20]  # type: ignore

    def test_invalid_window_sizes_empty(self):
        """Empty window list should raise ValueError."""
        with pytest.raises(ValueError, match="window_sizes"):
            RollingWindowConfig(window_sizes=[])

    def test_invalid_window_sizes_non_positive(self):
        """Non-positive window sizes should raise ValueError."""
        with pytest.raises(ValueError, match="window_sizes"):
            RollingWindowConfig(window_sizes=[0, -5])

    def test_invalid_window_sizes_type(self):
        """Non-integer window sizes should raise TypeError."""
        with pytest.raises(TypeError):
            RollingWindowConfig(window_sizes=["10", 20])

    def test_invalid_min_periods(self):
        """min_periods must be positive if provided."""
        with pytest.raises(ValueError, match="min_periods"):
            RollingWindowConfig(window_sizes=[10], min_periods=0)

    def test_invalid_zscore_threshold(self):
        """zscore_threshold must be positive."""
        with pytest.raises(ValueError, match="zscore_threshold"):
            RollingWindowConfig(window_sizes=[10], zscore_threshold=0)

    def test_duplicate_window_sizes(self):
        """Duplicate window sizes should be deduplicated or raise."""
        config = RollingWindowConfig(window_sizes=[10, 10, 20])
        # Should either dedupe or raise; we accept either but test consistency
        assert len(config.window_sizes) >= 2


