class TestComputeRollingStatistics:
    """Tests for rolling mean/std/z-score/rate-of-change computation."""

    def test_basic_rolling_mean(self, sample_telemetry, default_config):
        """Rolling mean should match pandas reference implementation."""
        result = compute_rolling_statistics(sample_telemetry, default_config)

        # Verify output structure
        assert isinstance(result, pd.DataFrame)
        assert "window_5_mean" in result.columns
        assert "window_10_mean" in result.columns
        assert "window_20_mean" in result.columns

        # Compare with pandas reference
        reference = sample_telemetry.rolling(window=5, min_periods=5).mean()
        pd.testing.assert_series_equal(
            result["window_5_mean"],
            reference,
            check_names=False,
        )

    def test_rolling_std(self, sample_telemetry, default_config):
        """Rolling std should match pandas reference."""
        result = compute_rolling_statistics(sample_telemetry, default_config)
        reference = sample_telemetry.rolling(window=10, min_periods=10).std()
        pd.testing.assert_series_equal(
            result["window_10_std"],
            reference,
            check_names=False,
        )

    def test_zscore_computation(self, sample_telemetry, default_config):
        """Z-score should be (x - mean) / std within window."""
        result = compute_rolling_statistics(sample_telemetry, default_config)

        # Manually compute z-score for window 5
        rolling_mean = sample_telemetry.rolling(5, min_periods=5).mean()
        rolling_std = sample_telemetry.rolling(5, min_periods=5).std()
        expected_zscore = (sample_telemetry - rolling_mean) / rolling_std

        pd.testing.assert_series_equal(
            result["window_5_zscore"],
            expected_zscore,
            check_names=False,
            check_exact=False,
            rtol=1e-6,
        )

    def test_rate_of_change(self, sample_telemetry, default_config):
        """Rate-of-change should be (x_t - x_{t-1}) / x_{t-1}."""
        result = compute_rolling_statistics(sample_telemetry, default_config)

        # Manual computation for window 10
        shifted = sample_telemetry.shift(10)
        expected_roc = (sample_telemetry - shifted) / shifted

        pd.testing.assert_series_equal(
            result["window_10_rate_of_change"],
            expected_roc,
            check_names=False,
            check_exact=False,
            rtol=1e-6,
        )

    def test_min_periods_override(self, sample_telemetry):
        """Custom min_periods should be respected."""
        config = RollingWindowConfig(
            window_sizes=[10],
            min_periods=5,
            include_zscore=False,
            include_rate_of_change=False,
        )
        result = compute_rolling_statistics(sample_telemetry, config)

        reference = sample_telemetry.rolling(window=10, min_periods=5).mean()
        pd.testing.assert_series_equal(
            result["window_10_mean"],
            reference,
            check_names=False,
        )

    def test_constant_series(self, constant_series, default_config):
        """Constant series should produce zero std and NaN z-scores."""
        result = compute_rolling_statistics(constant_series, default_config)

        # Std should be zero (or very close)
        assert np.allclose(result["window_5_std"].dropna(), 0.0, atol=1e-10)

        # Z-score should be NaN where std is zero
        assert result["window_5_zscore"].isna().all()

    def test_short_series(self):
        """Series shorter than window size should produce all-NaN stats."""
        short_series = pd.Series([1.0, 2.0, 3.0])
        config = RollingWindowConfig(
            window_sizes=[10],
            include_zscore=False,
            include_rate_of_change=False,
        )
        result = compute_rolling_statistics(short_series, config)
        assert result["window_10_mean"].isna().all()

    def test_nan_handling(self):
        """NaN values in input should propagate correctly."""
        series = pd.Series([1.0, np.nan, 3.0, 4.0, 5.0])
        config = RollingWindowConfig(
            window_sizes=[3],
            include_zscore=False,
            include_rate_of_change=False,
        )
        result = compute_rolling_statistics(series, config)
        # Window with NaN should produce NaN
        assert result["window_3_mean"].iloc[1] != result["window_3_mean"].iloc[1]  # NaN check

    def test_input_type_validation(self, default_config):
        """Non-Series input should raise TypeError."""
        with pytest.raises(TypeError):
            compute_rolling_statistics([1, 2, 3], default_config)

    def test_empty_series(self, default_config):
        """Empty series should return empty DataFrame with correct columns."""
        empty = pd.Series(dtype=float)
        result = compute_rolling_statistics(empty, default_config)
        assert result.empty
        assert "window_5_mean" in result.columns


