class TestDetectChangePoints:
    """Tests for change-point detection using ruptures."""

    def test_detects_known_change_point(self, series_with_change_point):
        """Should detect the change point near index 500."""
        result = detect_change_points(series_with_change_point, n_bkps=1)

        assert isinstance(result, list)
        assert len(result) >= 1
        # Change point should be within 10% of the true location
        assert abs(result[0] - 500) <= 50

    def test_no_change_point_constant(self, constant_series):
        """Constant series should yield no change points (or minimal)."""
        result = detect_change_points(constant_series, n_bkps=1)
        # With no variance, algorithm may still find a point; accept but verify
        # it doesn't crash and returns list
        assert isinstance(result, list)

    def test_n_bkps_zero(self, sample_telemetry):
        """n_bkps=0 should return empty list."""
        result = detect_change_points(sample_telemetry, n_bkps=0)
        assert result == []

    def test_n_bkps_exceeds_length(self, sample_telemetry):
        """n_bkps larger than series length should not crash."""
        result = detect_change_points(sample_telemetry, n_bkps=5000)
        assert isinstance(result, list)
        assert len(result) <= len(sample_telemetry)

    def test_algorithm_parameter(self, sample_telemetry):
        """Different algorithms should produce valid results."""
        for algo in ["PELT", "Binseg", "Window"]:
            result = detect_change_points(sample_telemetry, n_bkps=2, algorithm=algo)
            assert isinstance(result, list)
            assert len(result) <= 2

    def test_invalid_algorithm(self, sample_telemetry):
        """Invalid algorithm should raise ValueError."""
        with pytest.raises(ValueError):
            detect_change_points(sample_telemetry, n_bkps=1, algorithm="InvalidAlgo")

    def test_penalty_parameter(self, sample_telemetry):
        """Custom penalty should be accepted."""
        result = detect_change_points(sample_telemetry, n_bkps=2, penalty=10.0)
        assert isinstance(result, list)

    def test_short_series(self):
        """Very short series should not crash."""
        short = pd.Series([1.0, 2.0, 3.0])
        result = detect_change_points(short, n_bkps=1)
        assert isinstance(result, list)

    def test_nan_series(self):
        """NaN values should be handled or raise clear error."""
        series = pd.Series([1.0, np.nan, 3.0, 4.0, 5.0])
        with pytest.raises((ValueError, RuntimeError)):
            detect_change_points(series, n_bkps=1)


