class TestPerformance:
    """Performance sanity checks for high-throughput scenarios."""

    def test_large_dataset_throughput(self):
        """Should process 100k points in under 5 seconds."""
        rng = np.random.default_rng(0)
        large_series = pd.Series(rng.normal(0, 1, 100_000))
        config = RollingWindowConfig(
            window_sizes=[10, 50, 100],
            include_zscore=True,
            include_rate_of_change=True,
        )

        start = time.perf_counter()
        result = extract_features(large_series, config)
        elapsed = time.perf_counter() - start

        assert elapsed < 5.0, f"Processing took {elapsed:.2f}s, exceeded 5s budget"
        assert len(result) == 100_000

    def test_memory_footprint(self, sample_telemetry, default_config):
        """Output should not be excessively large."""
        result = extract_features(sample_telemetry, default_config)
        # 1000 rows * ~12 columns * 8 bytes = ~96KB, allow 10x headroom
        assert result.memory_usage(deep=True).sum() < 1_000_000


